import os
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in __import__('re').finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G), G['Demo pair 1 input'].__len__())

def f(g):
    H,W=len(g),len(g[0])
    out=[row[:] for row in g]
    seen=[[False]*W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            if g[i][j]==8 or seen[i][j]: continue
            # BFS over non-8 cells
            stack=[(i,j)]; seen[i][j]=True; cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<H and 0<=nx<W and g[ny][nx]!=8 and not seen[ny][nx]:
                        seen[ny][nx]=True; stack.append((ny,nx))
            ys=[c[0] for c in cells]; xs=[c[1] for c in cells]
            y0,y1,x0,x1=min(ys),max(ys),min(xs),max(xs)
            nz=[(y,x) for y,x in cells if g[y][x]!=0]
            if not nz: continue
            py0=min(p[0] for p in nz); py1=max(p[0] for p in nz)
            px0=min(p[1] for p in nz); px1=max(p[1] for p in nz)
            th=py1-py0+1; tw=px1-px0+1
            tile=[[0]*tw for _ in range(th)]
            for y,x in nz:
                tile[y-py0][x-px0]=g[y][x]
            for y in range(y0,y1+1):
                for x in range(x0,x1+1):
                    out[y][x]=tile[(y-y0)%th][(x-x0)%tw]
    return out

print(f(G['Demo pair 1 input'])==G['Demo pair 1 output'])
